ALTER POLICY "org read" ON public.org_settings USING (public.is_director(auth.uid()) OR (public.is_staff(auth.uid()) AND key IN ('organizacion','identidad','zonas','horarios','servicios','politicas','tarifas')));
ALTER POLICY "Dirección gestiona eventos" ON public.event_outbox USING (false) WITH CHECK (false);
ALTER POLICY "audit insert" ON public.audit_log WITH CHECK (false);
CREATE OR REPLACE FUNCTION public.guard_reserved_preparation() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
IF auth.uid() IS NULL THEN RETURN NEW; END IF;
IF TG_OP='UPDATE' AND (OLD.kind LIKE 'finance_%' OR OLD.kind='administrative_import_preparation') THEN RAISE EXCEPTION 'Preparación inmutable: registra otra revisión'; END IF;
IF NEW.kind LIKE 'finance_%' OR NEW.kind='administrative_import_preparation' THEN
IF NOT public.is_director(auth.uid()) OR NEW.scope<>'director' OR NEW.created_by IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Preparación reservada a Dirección'; END IF;
IF NEW.kind='administrative_import_preparation' THEN
IF TG_OP<>'INSERT' OR NEW.status<>'PREPARED_DRAFT' OR NEW.owner_id IS DISTINCT FROM auth.uid() OR NEW.id::text IS DISTINCT FROM NEW.data->>'requestId' OR jsonb_typeof(NEW.data) IS DISTINCT FROM 'object' OR (NEW.data-ARRAY['requestId','source','fingerprint','rowCount','mapping','authorizedFile','mappingReviewed','evidence','comparedAt','conflictCount'])<>'{}'::jsonb OR (NEW.data->>'authorizedFile') IS DISTINCT FROM 'true' OR (NEW.data->>'mappingReviewed') IS DISTINCT FROM 'true' OR coalesce(NEW.data->>'fingerprint','') !~ '^[a-f0-9]{64}$' OR length(coalesce(NEW.data->>'evidence',''))<10 OR length(coalesce(NEW.data->>'evidence',''))>1000 OR jsonb_typeof(NEW.data->'mapping') IS DISTINCT FROM 'object' OR coalesce(NEW.data->>'rowCount','') !~ '^\d+$' OR coalesce(NEW.data->>'comparedAt','')='' THEN RAISE EXCEPTION 'Solo metadatos de preparación revisada; sin archivo ni autorización oficial'; END IF;
IF (NEW.data->>'rowCount')::integer NOT BETWEEN 1 AND 2000 OR (NEW.data->>'comparedAt')::timestamptz < now()-interval '2 minutes' OR (NEW.data->>'comparedAt')::timestamptz > now()+interval '5 seconds' THEN RAISE EXCEPTION 'Revisión desactualizada o número de filas inválido'; END IF;
ELSE IF NEW.status<>'requested' THEN RAISE EXCEPTION 'Borrador financiero no equivale a pago verificado'; END IF; END IF; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.guard_reserved_preparation() FROM PUBLIC,anon,authenticated;